 function startDaily(){if(pool.length<dailyCount){M(`Solo hay ${pool.length} preguntas distintas. Elige una cantidad menor.`);return;}const date=dailyDate();const seed=date+session.user.id;const ordered=[...pool].sort((a,b)=>keyOf(a).localeCompare(keyOf(b)));const arr=seeded(ordered,seed).slice(0,dailyCount).map(q=>{const order=seeded(q.options.map((_,i)=>i),seed+keyOf(q));return {...q,options:order.map(i=>q.options[i]),correctIndex:order.indexOf(q.correctIndex)};});Mode(dailyMode);M("");start({id:"",title:`Reto diario · ${date}`,source_name:"",questions:arr,created_at:new Date().toISOString()},arr,"daily",dailyCount);}
